CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),email TEXT UNIQUE NOT NULL,full_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE companies(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),owner_user_id UUID NOT NULL REFERENCES users(id),name TEXT,description TEXT,business_model TEXT,stage TEXT,primary_goal TEXT,confidence_score INTEGER CHECK(confidence_score BETWEEN 0 AND 100),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE conversations(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),company_id UUID NOT NULL REFERENCES companies(id),channel TEXT NOT NULL DEFAULT 'web',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE messages(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),conversation_id UUID NOT NULL REFERENCES conversations(id),role TEXT NOT NULL CHECK(role IN ('user','assistant','system')),content TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE strategic_priorities(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),company_id UUID NOT NULL REFERENCES companies(id),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',priority_order INTEGER NOT NULL,rationale TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE strategic_journal(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),company_id UUID NOT NULL REFERENCES companies(id),event_type TEXT NOT NULL,summary TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
